import torch.nn as nn
enabled = False
class Cell(nn.Module):
    def __init__(self):
        super().__init__()
        self.child = nn.Identity()
    @property
    def opaque(self):
        return unknown()
    def helper(self, value):
        if enabled:
            ignored = self.opaque
            return self.child(value)
        return value
    def forward(self, value):
        value = self.helper(value)
        return self.child(value)
